#!/usr/bin/env python3
"""A small persistent JSON-over-HTTP key-value service."""

from __future__ import annotations

import argparse
import copy
import json
import logging
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import urlsplit, unquote_to_bytes


MAX_BODY_BYTES = 1024 * 1024
LOG = logging.getLogger("http-kv")
MISSING = object()


class StorageError(RuntimeError):
    pass


def reject_nonstandard_constant(value: str) -> None:
    raise ValueError(f"invalid JSON constant {value}")


def json_is_finite(value: Any) -> bool:
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, list):
        return all(json_is_finite(item) for item in value)
    if isinstance(value, dict):
        return all(isinstance(key, str) and json_is_finite(item) for key, item in value.items())
    return True


class KVStore:
    """In-memory state protected by one lock and durably saved after mutations."""

    def __init__(self, data_path: Path) -> None:
        self.data_path = data_path
        self._entries: dict[str, dict[str, Any]] = {}
        self._lock = threading.RLock()
        self._load()

    @staticmethod
    def _is_live(record: dict[str, Any], now: float) -> bool:
        expires_at = record.get("expires_at")
        return expires_at is None or expires_at > now

    def _load(self) -> None:
        if not self.data_path.exists():
            return
        try:
            with self.data_path.open("r", encoding="utf-8") as file:
                document = json.load(file, parse_constant=reject_nonstandard_constant)
            if not isinstance(document, dict) or not isinstance(document.get("entries"), dict):
                raise ValueError("expected an object with an entries object")
            now = time.time()
            for key, record in document["entries"].items():
                if (
                    not isinstance(key, str)
                    or not isinstance(record, dict)
                    or "value" not in record
                    or set(record) - {"value", "expires_at"}
                    or not json_is_finite(record["value"])
                ):
                    raise ValueError("invalid entry")
                expires_at = record.get("expires_at")
                if expires_at is not None and (
                    isinstance(expires_at, bool)
                    or not isinstance(expires_at, (int, float))
                    or not math.isfinite(expires_at)
                ):
                    raise ValueError("invalid expiry")
                normalized = {"value": record["value"], "expires_at": expires_at}
                if self._is_live(normalized, now):
                    self._entries[key] = normalized
            # Rewrite if expired records were discarded, so they cannot reappear.
            if len(self._entries) != len(document["entries"]):
                self._save_locked()
        except (OSError, ValueError, TypeError, json.JSONDecodeError) as exc:
            raise StorageError(f"cannot load data file {self.data_path}: {exc}") from exc

    def _save_locked(self) -> None:
        self.data_path.parent.mkdir(parents=True, exist_ok=True)
        payload = {"entries": self._entries}
        temp_name: str | None = None
        try:
            fd, temp_name = tempfile.mkstemp(
                prefix=f".{self.data_path.name}.", suffix=".tmp", dir=self.data_path.parent
            )
            with os.fdopen(fd, "w", encoding="utf-8") as file:
                json.dump(payload, file, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
                file.flush()
                os.fsync(file.fileno())
            os.replace(temp_name, self.data_path)
            temp_name = None
        except (OSError, TypeError, ValueError) as exc:
            raise StorageError(f"cannot save data file {self.data_path}: {exc}") from exc
        finally:
            if temp_name is not None:
                try:
                    os.unlink(temp_name)
                except OSError:
                    pass

    def _purge_expired_locked(self) -> bool:
        now = time.time()
        expired = [key for key, item in self._entries.items() if not self._is_live(item, now)]
        for key in expired:
            del self._entries[key]
        return bool(expired)

    def get(self, key: str) -> Any:
        with self._lock:
            if self._purge_expired_locked():
                self._save_after_expiry_locked()
            record = self._entries.get(key)
            return MISSING if record is None else copy.deepcopy(record["value"])

    def keys(self) -> list[str]:
        with self._lock:
            if self._purge_expired_locked():
                self._save_after_expiry_locked()
            return sorted(self._entries)

    def put(self, key: str, value: Any, ttl_seconds: float | None) -> bool:
        with self._lock:
            self._purge_expired_locked()
            existed = key in self._entries
            previous = copy.deepcopy(self._entries.get(key, MISSING))
            expiry = None if ttl_seconds is None else time.time() + ttl_seconds
            self._entries[key] = {"value": value, "expires_at": expiry}
            try:
                self._save_locked()
            except StorageError:
                if previous is MISSING:
                    self._entries.pop(key, None)
                else:
                    self._entries[key] = previous
                raise
            return existed

    def delete(self, key: str) -> bool:
        with self._lock:
            self._purge_expired_locked()
            previous = self._entries.get(key, MISSING)
            if previous is MISSING:
                return False
            del self._entries[key]
            try:
                self._save_locked()
            except StorageError:
                self._entries[key] = previous
                raise
            return True

    def _save_after_expiry_locked(self) -> None:
        try:
            self._save_locked()
        except StorageError:
            LOG.exception("could not persist expired-entry cleanup")


def valid_percent_encoding(value: str) -> bool:
    index = 0
    while index < len(value):
        if value[index] == "%":
            if index + 2 >= len(value) or any(char not in "0123456789abcdefABCDEF" for char in value[index + 1:index + 3]):
                return False
            index += 3
        else:
            index += 1
    return True


def decode_key(segment: str) -> str | None:
    if not segment or not valid_percent_encoding(segment):
        return None
    try:
        key = unquote_to_bytes(segment).decode("utf-8", "strict")
    except UnicodeDecodeError:
        return None
    return key if key and "/" not in key else None


class Handler(BaseHTTPRequestHandler):
    store: KVStore
    protocol_version = "HTTP/1.1"

    def log_message(self, format: str, *args: Any) -> None:
        LOG.info("%s - %s", self.address_string(), format % args)

    def _respond(self, status: int, payload: Any | None = None) -> None:
        encoded = b"" if payload is None else json.dumps(payload, ensure_ascii=False, allow_nan=False, separators=(",", ":")).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(encoded)))
        self.end_headers()
        if encoded:
            self.wfile.write(encoded)

    def _error(self, status: int, message: str) -> None:
        self._respond(status, {"error": message})

    def _key_for_request(self) -> str | None:
        path = urlsplit(self.path).path
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        segment = path[len(prefix):]
        if "/" in segment:
            return None
        return decode_key(segment)

    def _read_json(self) -> Any | None:
        if self.headers.get("Transfer-Encoding"):
            self._error(HTTPStatus.BAD_REQUEST, "transfer encoding is not supported")
            return None
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            self._error(HTTPStatus.LENGTH_REQUIRED, "Content-Length is required")
            return None
        try:
            length = int(raw_length)
        except ValueError:
            self._error(HTTPStatus.BAD_REQUEST, "invalid Content-Length")
            return None
        if length < 0:
            self._error(HTTPStatus.BAD_REQUEST, "invalid Content-Length")
            return None
        if length > MAX_BODY_BYTES:
            self._error(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, "request body exceeds 1 MiB")
            return None
        raw = self.rfile.read(length)
        if len(raw) != length:
            self._error(HTTPStatus.BAD_REQUEST, "incomplete request body")
            return None
        try:
            return json.loads(raw.decode("utf-8"), parse_constant=reject_nonstandard_constant)
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError):
            self._error(HTTPStatus.BAD_REQUEST, "malformed JSON")
            return None

    def do_PUT(self) -> None:
        key = self._key_for_request()
        if key is None:
            self._error(HTTPStatus.BAD_REQUEST, "invalid key or route")
            return
        body = self._read_json()
        if body is None:
            return
        if not isinstance(body, dict) or "value" not in body or set(body) - {"value", "ttl_seconds"} or not json_is_finite(body["value"]):
            self._error(HTTPStatus.BAD_REQUEST, "body must be an object with value and optional ttl_seconds")
            return
        ttl = body.get("ttl_seconds")
        if ttl is not None and (
            isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0
        ):
            self._error(HTTPStatus.BAD_REQUEST, "ttl_seconds must be a finite number greater than zero")
            return
        try:
            existed = self.store.put(key, body["value"], ttl)
        except StorageError:
            LOG.exception("PUT persistence failure")
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "could not persist data")
            return
        self._respond(HTTPStatus.OK if existed else HTTPStatus.CREATED, {"key": key, "value": body["value"]})

    def do_GET(self) -> None:
        path = urlsplit(self.path).path
        if path == "/health":
            self._respond(HTTPStatus.OK, {"status": "ok"})
            return
        if path == "/v1/keys":
            self._respond(HTTPStatus.OK, {"keys": self.store.keys()})
            return
        key = self._key_for_request()
        if key is None:
            self._error(HTTPStatus.NOT_FOUND, "unknown route")
            return
        try:
            value = self.store.get(key)
        except StorageError:
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "could not persist data")
            return
        if value is MISSING:
            self._error(HTTPStatus.NOT_FOUND, "key not found")
            return
        self._respond(HTTPStatus.OK, {"key": key, "value": value})

    def do_DELETE(self) -> None:
        key = self._key_for_request()
        if key is None:
            self._error(HTTPStatus.BAD_REQUEST, "invalid key or route")
            return
        try:
            deleted = self.store.delete(key)
        except StorageError:
            LOG.exception("DELETE persistence failure")
            self._error(HTTPStatus.INTERNAL_SERVER_ERROR, "could not persist data")
            return
        if not deleted:
            self._error(HTTPStatus.NOT_FOUND, "key not found")
            return
        self._respond(HTTPStatus.NO_CONTENT)

    def do_POST(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")

    def do_PATCH(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")

    def do_HEAD(self) -> None:
        self._error(HTTPStatus.METHOD_NOT_ALLOWED, "method not allowed")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", required=True, type=int)
    parser.add_argument("--data", required=True, type=Path)
    arguments = parser.parse_args()
    if not 0 <= arguments.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return arguments


def main() -> int:
    arguments = parse_args()
    logging.basicConfig(level=logging.INFO, stream=sys.stderr, format="%(asctime)s %(levelname)s %(message)s")
    try:
        Handler.store = KVStore(arguments.data)
    except StorageError as exc:
        LOG.error("%s", exc)
        return 1
    server = ThreadingHTTPServer((arguments.host, arguments.port), Handler)
    server.daemon_threads = True
    stopping = threading.Event()

    def stop(signum: int, frame: Any) -> None:
        if not stopping.is_set():
            stopping.set()
            LOG.info("received signal %d; shutting down", signum)
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_port}", flush=True)
    try:
        server.serve_forever()
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

